import { http, HttpResponse, type RequestHandler } from 'msw'
import type { components } from '@/types/api.generated'

type LoginResponse = components['schemas']['LoginResponse']
type RegisterResponse = components['schemas']['RegisterResponse']

const loginResponse = {
  expiraEn: '2030-01-01T00:00:00Z',
} satisfies LoginResponse

const registerResponse = {
  mensaje: 'Registration simulated.',
  correo: 'demo.user@example.test',
} satisfies RegisterResponse

export const handlers: RequestHandler[] = [
  http.post('/api/Auth/login', () =>
    HttpResponse.json(loginResponse, { status: 200 }),
  ),
  http.post('/api/Auth/register', () =>
    HttpResponse.json(registerResponse, { status: 200 }),
  ),
  http.post('/api/Concursos/crear', async ({ request }) => {
    const formData = await request.formData()
    const nombre = formData.get('nombre')
    const codigo = formData.get('codigo')
    if (typeof nombre !== 'string' || !nombre.trim())
      return HttpResponse.json(
        { mensaje: 'El nombre del concurso es obligatorio.' },
        { status: 400 },
      )
    if (codigo === 'unauthorized')
      return HttpResponse.json({ mensaje: 'Token inválido' }, { status: 401 })
    return HttpResponse.json(
      {
        codigo: 'contest-demo',
        mensaje: 'Concurso, problemas y casos de prueba creados exitosamente.',
      },
      { status: 200 },
    )
  }),
]

import { describe, expect, it } from 'vitest'
import { createContestSchema } from './schema'
import { problemLetter } from './types'

const validValues = () => ({
  nombre: 'Contest',
  descripcion: 'Description',
  fechaInicio: '2026-07-19T12:00',
  duracionMinutos: 120,
  contrasena: '',
  urlSetProblemas: 'https://example.test/problems',
  minutosCongelamiento: 30,
  codigo: 'C-1',
  listaProblemas: [{ titulo: 'A problem', tiempo: 1.5, memoria: 256 }],
  archivoZip: new File(['zip'], 'cases.ZIP', { type: 'application/zip' }),
})

describe('create contest schema', () => {
  it('accepts the required form values and a case-insensitive ZIP extension', () => {
    expect(createContestSchema.safeParse(validValues()).success).toBe(true)
  })

  it('rejects blank required fields, invalid problem values, and a non-ZIP file', () => {
    const invalid = validValues()
    invalid.nombre = ' '
    invalid.duracionMinutos = 0
    invalid.listaProblemas[0].memoria = 1.5
    invalid.archivoZip = new File(['text'], 'cases.txt')

    expect(createContestSchema.safeParse(invalid).success).toBe(false)
  })

  it('rejects freezing longer than the contest and more than 26 problems', () => {
    const invalid = validValues()
    invalid.minutosCongelamiento = 121
    invalid.listaProblemas = Array.from({ length: 27 }, () => ({
      titulo: 'Problem',
      tiempo: 1,
      memoria: 256,
    }))

    expect(createContestSchema.safeParse(invalid).success).toBe(false)
  })
})

describe('problem letters', () => {
  it('derives consecutive letters from the current array index', () => {
    expect([0, 1, 25].map(problemLetter)).toEqual(['A', 'B', 'Z'])
  })
})

import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { act, renderHook } from '@testing-library/react'
import type { PropsWithChildren } from 'react'
import { describe, expect, it, vi } from 'vitest'
import type { CreateContestFormValues } from './types'

const createContest = vi.fn()
vi.mock('./service', () => ({ createContest }))

import { useCreateContestMutation } from './use-create-contest'

const values: CreateContestFormValues = {
  nombre: 'Contest',
  descripcion: 'Description',
  fechaInicio: '2026-07-19T12:00',
  duracionMinutos: 60,
  contrasena: '',
  urlSetProblemas: 'https://example.test/problems',
  minutosCongelamiento: 0,
  codigo: 'C-1',
  listaProblemas: [{ titulo: 'Problem', tiempo: 1, memoria: 256 }],
  archivoZip: new File(['zip'], 'cases.zip'),
}

const wrapper = ({ children }: PropsWithChildren) => (
  <QueryClientProvider client={new QueryClient({ defaultOptions: { queries: { retry: false }, mutations: { retry: false } } })}>
    {children}
  </QueryClientProvider>
)

describe('useCreateContestMutation', () => {
  it('delegates once to the creation service and exposes success and reset', async () => {
    createContest.mockResolvedValue({ codigo: 'contest-demo', mensaje: 'Created' })
    const { result } = renderHook(() => useCreateContestMutation(), { wrapper })

    await act(async () => result.current.mutateAsync(values))

    expect(createContest).toHaveBeenCalledTimes(1)
    expect(result.current.data).toEqual({ codigo: 'contest-demo', mensaje: 'Created' })
    act(() => result.current.reset())
    expect(result.current.data).toBeUndefined()
  })
})

